// Webhook de base de données Supabase (INSERT sur messages).
// Ne garde que les messages sortants mis en file depuis la plateforme.
const { headers, body } = $input.first().json;
if (headers['x-closer-secret'] !== $env.CLOSER_WEBHOOK_SECRET) {
  throw new Error('Secret du webhook Supabase invalide');
}
const r = body.record || {};
if (body.table !== 'messages' || r.direction !== 'outbound' || r.status !== 'queued') return [];
// UPDATE : seul le passage « en attente de validation » → « en file » déclenche un envoi.
if (body.type === 'UPDATE' && (body.old_record || {}).status !== 'pending_approval') return [];
return [{ json: { message_id: r.id } }];

// Construit l'appel Graph API selon le canal du message.
const p = $input.first().json;
const graph = 'https://graph.facebook.com/' + ($env.META_GRAPH_VERSION || 'v23.0');
const fail = (error) => [{ json: { message_id: p.message_id, url: null, error } }];

if (p.status !== 'queued') return [];
if (!p.access_token) return fail('Canal non connecté (token absent)');

let url, payload;
if (p.channel === 'whatsapp' && p.template) {
  // Modèle approuvé (relance) : autorisé hors fenêtre de 24 h.
  url = `${graph}/${p.account_external_id}/messages`;
  payload = {
    messaging_product: 'whatsapp',
    to: p.recipient,
    type: 'template',
    template: {
      name: p.template.name,
      language: { code: p.template.language },
      components: [{
        type: 'body',
        parameters: (p.template.params || []).map((text) => ({ type: 'text', text: String(text) })),
      }],
    },
  };
  return [{ json: { message_id: p.message_id, url, token: p.access_token, payload } }];
}

if (!p.window_open) return fail('Fenêtre de 24 h fermée : un modèle approuvé est nécessaire');
if (p.channel === 'whatsapp') {
  url = `${graph}/${p.account_external_id}/messages`;
  payload = { messaging_product: 'whatsapp', to: p.recipient, type: 'text', text: { body: p.body } };
} else if (p.channel === 'facebook' || p.channel === 'instagram') {
  // Messenger et Instagram : même endpoint, token de la Page.
  url = `${graph}/me/messages`;
  payload = { recipient: { id: p.recipient }, messaging_type: 'RESPONSE', message: { text: p.body } };
} else {
  return fail(`Le canal ${p.channel} est en mode assisté : envoi manuel uniquement`);
}

return [{ json: { message_id: p.message_id, url, token: p.access_token, payload } }];
